    if decrease_per_well <= 0:
        raise ValueError("decrease_per_well must be positive")
    max_yield = yield_per_well // decrease_per_well  # cannot exceed zero yield
    if max_yield < 0:
        max_yield = 0

    # theoretical optimum (real number)
    n_opt = (yield_per_well - initial_wells * decrease_per_well) / (2 * decrease_per_well)

    # candidate integers around n_opt, bounded by [0, max_yield]
    candidates = {0, max_yield}
    for n in (int(n_opt), int(n_opt) + 1):
        if 0 <= n <= max_yield:
            candidates.add(n)

    best_n = max(candidates, key=lambda n: (initial_wells + n) * (yield_per_well - decrease_per_well * n))
    return best_n
