def calculate_grouped_std(intervals: List[Tuple[float, float]], freqs: List[int]) -> float:
    if len(intervals) != len(freqs):
        raise ValueError("Number of intervals must equal number of frequencies.")
    if any(f < 0 for f in freqs):
        raise ValueError("Frequencies must be non-negative.")
    if any(l >= u for l, u in intervals):
        raise ValueError("Lower bound must be less than upper bound for each interval.")
    total = sum(freqs)
    if total == 0:
        raise ValueError("Total frequency cannot be zero.")
    midpoints = [(l + u) / 2 for l, u in intervals]
    mean = sum(f * m for f, m in zip(freqs, midpoints)) / total
    variance = sum(f * (m - mean) ** 2 for f, m in zip(freqs, midpoints)) / total
    std = math.sqrt(variance)
    return round(std, 2)

