def solve_max_profit(initial_price=30, initial_orders=60, initial_qty=100,
                     price_step=2, order_dec=4, qty_dec=2, cost_price=24, max_price=50):
    best_price = None
    best_profit = -1
    step = 0
    while True:
        price = initial_price + step * price_step
        if price > max_price:
            break
        orders = initial_orders - step * order_dec
        if orders < 0:
            break
        qty_per_order = initial_qty - step * qty_dec
        if qty_per_order < 0:
