def calculate_probability_score(questions: int, options: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    if questions < 0 or options <= 0:
        raise ValueError("Invalid parameters")
    if options == 1:
        net = correct_points * questions
        return 100.0 if net == target_score else 0.0

