def _get_distance(u: str, v: str, graph: Dict[Tuple[str, str], float]) -> float:
    if (u, v) in graph:
        return graph[(u, v)]
    if (v, u) in graph:
        return graph[(v, u)]
    raise ValueError(f"Missing distance between {u} and {v}")

def _edge_valid(u: str, v: str) -> bool:
    # Only A -> B is allowed; B -> A is forbidden
    if u == "A" and v == "B":
        return True
    if u == "B" and v == "A":
        return False
    return True

def solve_shortest_path(graph: Dict[Tuple[str, str], float]) -> float:
    nodes = ["A", "B", "C", "D"]
    best = math.inf

    for perm in permutations(nodes):
        total = 0.0
        valid = True

        # M -> first node
        total += _get_distance("M", perm[0], graph)

        # consecutive nodes
        for i in range(3):
            u, v = perm[i], perm[i + 1]
            if not _edge_valid(u, v):
                valid = False
                break
            total += _get_distance(u, v, graph)

        if valid and total < best:
            best = total

    if best == math.inf:
        raise ValueError("No valid path found")
    return best
