def count_grid_ways(numbers: List[int]) -> int:
    """
    Count the number of ways to select six distinct numbers from `numbers`
    and arrange them in a 3‑2‑1 grid such that each row has the same sum.
    """
    if not numbers:
        return 0

    # Ensure all numbers are distinct; duplicates cannot be used.
    if len(set(numbers)) != len(numbers):
        return 0

    total = 0
    nums_set = set(numbers)

    # Iterate over each possible middle row (single cell) value `a`
    for a in nums_set:
        # Find unordered pairs (b, c) that sum to `a`
        for b, c in combinations(nums_set - {a}, 2):
            if b + c != a:
                continue
            # Remaining numbers after removing a, b, c
            remaining = nums_set - {a, b, c}
            # Find unordered triples from remaining that sum to `a`
            for triple in combinations(remaining, 3):
                if sum(triple) == a:
                    total += 1

    return total
