def count_rotor_arrangements(n: int, masses: list[int]) -> int:
    assert n == 9 and len(masses) == 9
    total = sum(masses)
    if total % 3 != 0:
        return 0
    target = total // 3
    subsets = [tuple(sorted(combo)) for combo in combinations(masses, 3) if sum(combo) == target]
    count = 0
    for s0 in subsets:
        rem0 = set(masses) - set(s0)
        for s1 in subsets:
            if s1 <= rem0:
                continue
            rem1 = rem0 - set(s1)
            if not rem1:
                continue
            s2 = tuple(sorted(rem1))
            if s2 not in subsets:
                continue
            count += 1
    return count * 6 ** 3

