from math import comb
from typing import Union

def calculate_probability_score(
    n: int,
    options: int,
    points_per_correct: int,
    points_per_incorrect: int,
    target: int
) -> float:
    """
    Returns 100 * probability that a student scores exactly `target` points
    when answering `n` multiple‑choice questions (4 options each) with random choice.
    """
    # Basic validation
    if n <= 0 or options <= 0:
        raise ValueError("n and options must be positive integers.")
    if not isinstance(points_per_correct, int) or not isinstance(points_per_incorrect, int):
        raise TypeError("points_per_correct and points_per_incorrect must be integers.")
    if not isinstance(target, int):
        raise TypeError("target must be an integer.")

    # Special case: equal point values for correct/incorrect
    if points_per_correct == points_per_incorrect:
        expected_score = points_per_correct * n
        if target == expected_score:
            return round(100.0, 2)
        return 0.0

    # Solve for required number of correct answers
    numerator = target - points_per_incorrect * n
    denominator = points_per_correct - points_per_incorrect
    if denominator == 0:
        raise ValueError("points_per_correct and points_per_incorrect cannot be equal (handled above).")

    if numerator % denominator != 0:
        return 0.0  # impossible integer count of correct answers

    c = numerator // denominator
    if not (0 <= c <= n):
        return 0.0  # out of range

    # Binomial probability
    prob = comb(n, c) * (1 / options) ** c * ((options - 1) / options) ** (n - c)
    return round(100.0 * prob, 2)

