def _valid_vectors(slots: int, books: int) -> List[List[int]]:
    res = []
    for vec in product([0, 1, 2], repeat=slots):
        if sum(vec) != books:
            continue
        ones = sum(1 for v in vec if v == 1)
        if ones not in (4, 6):
            continue
        ok = True
        for i, v in enumerate(vec):
            if v == 2:
                if i > 0 and vec[i - 1] != 0:
                    ok = False
                    break
                if i < slots - 1 and vec[i + 1] != 0:
                    ok = False
