def maximize_oil_production(initial_wells: int, avg_yield: int, decrease_per_well: int) -> int:
    """
    Returns the number of additional wells to drill to maximize total daily oil production.
    """
    if decrease_per_well <= 0:
        raise ValueError("decrease_per_well must be positive")
    if initial_wells < 0 or avg_yield < 0:
        raise ValueError("initial_wells and avg_yield must be non-negative")

    # Vertex of the quadratic f(k) = (initial_wells + k) * (avg_yield - decrease_per_well * k)
    # k_opt = (avg_yield - initial_wells * decrease_per_well) / (2 * decrease_per_well)
    k_opt = (avg_yield - initial_wells * decrease_per_well) / (2 * decrease_per_well)

    # The optimal integer k is the nearest integer to k_opt, but cannot be negative.
    k_floor = max(0, int(k_opt) - 1)
    k_ceil = max(0, int(k_opt) + 1)

    # Evaluate production at both candidates and pick the better one.
    def total_production(k: int) -> int:
        return (initial_wells + k) * (avg_yield - decrease_per_well * k)

    k_floor_prod = total_production(k_floor)
    k_ceil_prod = total_production(k_ceil)

    if k_floor_prod >= k_ceil_prod:
        return k_floor
    else:
