from math import comb
from typing import List

def calculate_probability(n: int, k: int) -> float:
    if not (0 <= k <= n):
        raise ValueError("Invalid parameters: 0 <= k <= n")

    # Determine prime counts
    primes = [i for i in range(2, n + 1) if all(i % d for d in range(2, int(i ** 0.5) + 1))]
    p_even = 1 if 2 in primes else 0
    p_odd = len(primes) - p_even

    n_even = sum(1 for i in range(2, n + 1) if i not in primes and i % 2 == 0)
    n_odd = sum(1 for i in range(2, n + 1) if i not in primes and i % 2 == 1)

    total = comb(n, k)
    favorable = 0

    max_x = min(k, p_even + p_odd)
    for x in range(2, max_x + 1):
        y = k - x
        if y < 0:
            continue

        max_o = min(x, p_odd)
        for o in range(max_o + 1):
            if x - o > p_even:
                continue
            for o_n in range(min(y, n_odd) + 1):
                if (o + o_n) % 2 != 0:
                    continue
                if y - o_n > n_even:
                    continue
                ways = comb(p_odd, o) * comb(p_even, x - o) * comb(n_odd, o_n) * comb(n_even, y - o_n)
                favorable += ways

    prob = favorable / total
    return round(prob * 100, 1)
